List<string> inventory = new List<string>();
bool playing = true;

while (playing)
{
    Console.WriteLine("\n=== INVENTORY ===" );
    Console.WriteLine($"Items: {inventory.Count}");
    Console.WriteLine("1. View items");
    Console.WriteLine("2. Add item");
    Console.WriteLine("3. Remove item");
    Console.WriteLine("4. Search item");
    Console.WriteLine("5. Exit");
    Console.Write("Choose: ");

    string choice = Console.ReadLine() ?? "";

    if (choice == "1")
    {
        if (inventory.Count == 0)
        {
            Console.WriteLine("Inventory empty.");
        }
        else
        {
            foreach (string item in inventory)
            {
                Console.WriteLine($"- {item}");
            }
        }
    }
    else if (choice == "2")
    {
        Console.Write("Item name: ");
        string item = Console.ReadLine() ?? "";
        if (!string.IsNullOrEmpty(item))
        {
            inventory.Add(item);
            Console.WriteLine("Added!");
        }
    }
    else if (choice == "3")
    {
        Console.Write("Item name to remove: ");
        string item = Console.ReadLine() ?? "";
        if (inventory.Remove(item))
        {
            Console.WriteLine("Removed!");
        }
        else
        {
            Console.WriteLine("Item not found.");
        }
    }
    else if (choice == "4")
    {
        Console.Write("Search for: ");
        string item = Console.ReadLine() ?? "";
        int pos = inventory.IndexOf(item);
        if (pos >= 0)
        {
            Console.WriteLine($"Found at position {pos + 1}");
        }
        else
        {
            Console.WriteLine("Not found.");
        }
    }
    else if (choice == "5")
    {
        playing = false;
    }
}
